{
  const { SemanticPipeline } = await import('./ci-cd/SemanticPipeline.js');
  const pipeline = new SemanticPipeline();
  return pipeline.run([filePath], {
    formalVerification: options.formal || false,
    criticalFunctions: options.critical || [],
  });
}

{
  const { Z3Verifier, createIntParam, range } = await import('./formal/index.js');
  const { Project } = await import('ts-morph');

  const project = new Project();
  const sourceFile = project.addSourceFileAtPath(filePath);
  const func = sourceFile.getFunction(functionName);

  if (!func) {
    throw new Error(`Function ${functionName} not found in ${filePath}`);
  }

  const verifier = new Z3Verifier();
  await verifier.initialize();

  const params = func.getParameters().map(p => createIntParam(p.getName()));
  const returnType = func.getReturnType();

  const result = await verifier.verifyFunction({
    name: functionName,
    params,
    returnType: returnType.isNumber() ? 'int' : 'void',
    preconditions: params.map(p => range(p.name, -1000, 1000)),
    postconditions: [],
    invariants: [],
  });

  await verifier.dispose();
  return result;
}

{
  const { Project } = await import('ts-morph');
  const { CFGAnalyzer } = await import('./semantic/CFGAnalyzer.js');

  const project = new Project();
  const sourceFile = project.addSourceFileAtPath(filePath);
  const analyzer = new CFGAnalyzer();

  return analyzer.build(sourceFile);
}

{
  const { CallGraphAnalyzer } = await import('./semantic/CallGraphAnalyzer.js');
  const analyzer = new CallGraphAnalyzer();

  return analyzer.analyze(entryPoint, maxDepth);
}

{
  const analyzer = new TypeAnalyzerClass(filePath);
  return analyzer.analyze();
}

{
  const { Project } = await import('ts-morph');
  const { DataFlowAnalyzer } = await import('./semantic/DataFlowAnalyzer.js');

  const project = new Project();
  const sourceFile = project.addSourceFileAtPath(filePath);
  const analyzer = new DataFlowAnalyzer();

  return analyzer.analyze(sourceFile);
}

{
  const { CLIExecutor } = await import('./cli/CLIExecutor.js');
  const cli = new CLIExecutor();
  await cli.run();
}

{
  const dir = path.dirname(filePath);
  if (tsConfigCache && tsConfigBaseDirCache === dir) {
    return tsConfigCache;
  }

  tsConfigBaseDirCache = dir;
  tsConfigCache = loadTsConfig(dir);
  return tsConfigCache;
}

{
  try {
    const resolvedPath = resolveAbsolutePath(filePath);
    if (!fs.existsSync(resolvedPath)) {
      console.warn(`⚠️ Файл не найден: ${resolvedPath}`);
      return null;
    }

    const source = fs.readFileSync(resolvedPath, 'utf-8');
    const { descriptor, errors } = parseVueSFC(source, {
      filename: resolvedPath,
      sourceMap: false,
    });

    if (errors.length > 0) {
      console.warn(`⚠️ Ошибки парсинга Vue файла ${resolvedPath}:`, errors);
    }

    const result: VueSFCData = {
      script: null,
      scriptSetup: null,
      template: null,
      styles: [],
      customBlocks: {},
      scriptType: null,
    };

    if (descriptor.script) {
      result.script = descriptor.script.content;
      result.scriptType = 'basic';
      if (descriptor.script.lang === 'ts') {
        result.scriptType = 'ts';
      }
    }

    if (descriptor.scriptSetup) {
      result.scriptSetup = descriptor.scriptSetup.content;
      result.scriptType = descriptor.scriptSetup.lang === 'ts' ? 'tsSetup' : 'setup';
    }

    // ✅ ДОБАВЛЯЕМ ПРОВЕРКУ НА ПУСТОЙ СКРИПТ
    const scriptContent = result.scriptSetup || result.script;
    if (scriptContent && scriptContent.trim() === '') {
      console.log(`ℹ️ Пустой script блок в ${path.basename(filePath)}, пропускаем`);
      return null;
    }

    if (descriptor.template) {
      result.template = descriptor.template.content;
    }

    result.styles = descriptor.styles.map(style => style.content);

    for (const [blockName, block] of Object.entries(descriptor.customBlocks || {})) {
      if (!result.customBlocks[blockName]) {
        result.customBlocks[blockName] = [];
      }
      result.customBlocks[blockName].push(block.content);
    }

    return result;
  } catch (error) {
    console.error(`❌ Ошибка парсинга Vue файла ${filePath}:`, error);
    return null;
  }
}

{
  const imports: { source: string; specifiers: string[]; isTypeOnly: boolean; line?: number }[] =
    [];

  if (!ast || !ast.body) return imports;

  walk(ast, {
    enter(node: any) {
      if (node.type === 'ImportDeclaration' && node.source) {
        const source = node.source.value;
        const specifiers: string[] = [];
        const isTypeOnly = node.importKind === 'type' || false;

        for (const spec of node.specifiers || []) {
          if (spec.type === 'ImportSpecifier') {
            const name = spec.imported?.name || spec.local?.name;
            if (name) specifiers.push(name);
          } else if (spec.type === 'ImportDefaultSpecifier') {
            const name = spec.local?.name;
            if (name) specifiers.push(`default as ${name}`);
          } else if (spec.type === 'ImportNamespaceSpecifier') {
            const name = spec.local?.name;
            if (name) specifiers.push(`* as ${name}`);
          }
        }

        if (source && specifiers.length > 0) {
          imports.push({
            source,
            specifiers,
            isTypeOnly,
            line: node.loc?.start?.line,
          });
        }
      }
    },
  });

  return imports;
}

{
  const exports: any[] = [];

  if (!ast || !ast.body) return exports;

  let reExportCount = 0;

  walk(ast, {
    enter(node: any) {
      // ============================================
      // 1. ExportNamedDeclaration с declaration
      // ============================================
      if (node.type === 'ExportNamedDeclaration' && node.declaration) {
        const decl = node.declaration;

        if (decl.type === 'FunctionDeclaration' && decl.id) {
          exports.push({
            name: decl.id.name,
            type: 'function',
            isDefault: false,
            line: node.loc?.start?.line,
            isReExport: false,
          });
        } else if (decl.type === 'ClassDeclaration' && decl.id) {
          exports.push({
            name: decl.id.name,
            type: 'class',
            isDefault: false,
            line: node.loc?.start?.line,
            isReExport: false,
          });
        } else if (decl.type === 'VariableDeclaration') {
          for (const d of decl.declarations) {
            if (d.id?.name) {
              exports.push({
                name: d.id.name,
                type: 'variable',
                isDefault: false,
                line: d.loc?.start?.line || node.loc?.start?.line,
                isReExport: false,
              });
            }
          }
        } else if (decl.type === 'TSInterfaceDeclaration' && decl.id) {
          exports.push({
            name: decl.id.name,
            type: 'interface',
            isDefault: false,
            line: node.loc?.start?.line,
            isReExport: false,
          });
        } else if (decl.type === 'TSTypeAliasDeclaration' && decl.id) {
          exports.push({
            name: decl.id.name,
            type: 'type',
            isDefault: false,
            line: node.loc?.start?.line,
            isReExport: false,
          });
        } else if (decl.type === 'TSEnumDeclaration' && decl.id) {
          exports.push({
            name: decl.id.name,
            type: 'enum',
            isDefault: false,
            line: node.loc?.start?.line,
            isReExport: false,
          });
        }
      }

      // ============================================
      // 2. ✅ РЕЭКСПОРТЫ: export { a, b } from 'module'
      // ============================================
      if (node.type === 'ExportNamedDeclaration' && node.specifiers && node.specifiers.length > 0) {
        const isReExport = !!node.source;
        const sourceModule = node.source?.value;

        if (isReExport && sourceModule) {
          reExportCount++;
          if (reExportCount <= 3) {
            console.log(`   🔄 Реэкспорт найден: из '${sourceModule}'`);
          }
        }

        for (const spec of node.specifiers) {
          if (spec.type === 'ExportSpecifier') {
            const exportedName = spec.exported?.name || spec.local?.name;
            if (exportedName) {
              // ✅ ПРАВИЛЬНО УСТАНАВЛИВАЕМ ФЛАГИ ДЛЯ РЕЭКСПОРТА
              exports.push({
                name: exportedName,
                type: isReExport ? 're-export' : 'named',
                isDefault: false,
                line: node.loc?.start?.line,
                isReExport: isReExport,
                source: sourceModule,
                specifier: spec.local?.name || spec.exported?.name,
              });
            }
          }
        }
      }

      // ============================================
      // 3. ExportDefaultDeclaration
      // ============================================
      if (node.type === 'ExportDefaultDeclaration' && node.declaration) {
        const decl = node.declaration;
        let name = 'default';
        let type = 'default';

        if (decl.type === 'FunctionDeclaration' && decl.id) {
          name = decl.id.name || 'default';
          type = 'function';
        } else if (decl.type === 'ClassDeclaration' && decl.id) {
          name = decl.id.name || 'default';
          type = 'class';
        } else if (decl.type === 'Identifier') {
          name = decl.name || 'default';
          type = 'value';
        } else if (decl.type === 'ObjectExpression') {
          name = 'default';
          type = 'object';
        } else if (decl.type === 'ArrowFunctionExpression') {
          name = 'default';
          type = 'function';
        }

        exports.push({
          name,
          type,
          isDefault: true,
          line: node.loc?.start?.line,
          isReExport: false,
        });
      }

      // ============================================
      // 4. ExportAllDeclaration: export * from 'module'
      // ============================================
      if (node.type === 'ExportAllDeclaration' && node.source) {
        exports.push({
          name: '*',
          type: 'all',
          isDefault: false,
          line: node.loc?.start?.line,
          isReExport: true,
          source: node.source.value,
        });
      }

      // ============================================
      // 5. ExportNamedDeclaration без declaration (только specifiers)
      // ============================================
      if (node.type === 'ExportNamedDeclaration' && !node.declaration && node.specifiers) {
        for (const spec of node.specifiers) {
          if (spec.type === 'ExportSpecifier') {
            const exportedName = spec.exported?.name || spec.local?.name;
            if (exportedName) {
              // ✅ ПРОВЕРЯЕМ, ЕСТЬ ЛИ source (это реэкспорт)
              const isReExport = !!node.source;
              const sourceModule = node.source?.value;

              exports.push({
                name: exportedName,
                type: isReExport ? 're-export' : 'named',
                isDefault: false,
                line: node.loc?.start?.line,
                isReExport: isReExport,
                source: sourceModule,
              });
            }
          }
        }
      }
    },
  });

  if (reExportCount > 0) {
    console.log(`   ✅ Найдено реэкспортов: ${reExportCount}`);
  }

  // Удаляем дубликаты (оставляем первое вхождение)
  const seen = new Set<string>();
  const unique = exports.filter(exp => {
    const key = `${exp.name}:${exp.isReExport ? 're' : 'normal'}:${exp.source || 'self'}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  return unique;
}

{
  try {
    // ✅ Нормализуем путь
    const resolvedPath = validateAndResolvePath(filePath);
    if (!resolvedPath) return null;

    // ✅ ПРОПУСК CSS-ФАЙЛОВ
    if (filePath.endsWith('.css')) {
      console.log(`⏭️ Пропуск CSS файла: ${path.basename(filePath)}`);
      return null;
    }

    // ✅ ПРОПУСК ДРУГИХ НЕПОДДЕРЖИВАЕМЫХ РАСШИРЕНИЙ
    const unsupportedExtensions = [
      '.css',
      '.scss',
      '.less',
      '.html',
      '.json',
      '.xml',
      '.svg',
      '.png',
      '.jpg',
      '.jpeg',
      '.gif',
      '.ico',
      '.woff',
      '.woff2',
      '.ttf',
      '.eot',
    ];
    const ext = path.extname(filePath);
    if (unsupportedExtensions.includes(ext)) {
      console.log(`⏭️ Пропуск неподдерживаемого файла: ${path.basename(filePath)}`);
      return null;
    }

    console.log(`📖 Чтение файла: ${resolvedPath}`);
    let code = fs.readFileSync(resolvedPath, 'utf-8');
    console.log(`📏 Размер файла: ${code.length} символов`);

    let isVue = false;
    let isTypeScript = false;
    const moduleName = path.basename(path.dirname(resolvedPath));
    let imports: { source: string; specifiers: string[]; isTypeOnly: boolean; line?: number }[] =
      [];
    let exports: {
      name: string;
      type: string;
      isDefault: boolean;
      line?: number;
      isReExport?: boolean;
      source?: string;
    }[] = [];

    if (filePath.endsWith('.vue')) {
      isVue = true;
      const sfc = parseVueSFCFile(resolvedPath);

      // ✅ ЕСЛИ SFC ВЕРНУЛ NULL — ПРОПУСКАЕМ ФАЙЛ
      if (!sfc) {
        console.log(
          `⏭️ Пропуск Vue файла (нет скрипта или пустой скрипт): ${path.basename(filePath)}`
        );
        return null;
      }

      const scriptType = sfc.scriptType || 'unknown';
      isTypeScript = scriptType === 'ts' || scriptType === 'tsSetup';

      const scriptContent = sfc.scriptSetup || sfc.script;

      if (!scriptContent) {
        console.warn(`⚠️ В Vue файле ${resolvedPath} не найден script блок`);
        return null;
      }

      // ✅ ПРОВЕРКА НА ПУСТОЙ СКРИПТ
      if (scriptContent.trim() === '') {
        console.log(`ℹ️ Пустой script блок в ${path.basename(filePath)}, пропускаем`);
        return null;
      }

      code = scriptContent;
      console.log(
        `📄 Vue файл: ${path.basename(resolvedPath)} (${scriptType}, TS: ${isTypeScript})`
      );

      if (sfc.styles.length > 0) {
        console.log(`   🎨 Styles: ${sfc.styles.length} блоков`);
      }
    } else {
      isTypeScript = filePath.endsWith('.ts') || filePath.endsWith('.tsx');
    }

    const parserOptions: ParserOptions = {
      ecmaVersion: 2026 as const,
      sourceType: 'module',
      loc: true,
      range: true,
      comment: true,
      tokens: true,
      ecmaFeatures: {
        jsx: filePath.endsWith('.tsx') || filePath.endsWith('.jsx'),
        globalReturn: false,
        impliedStrict: true,
      },
    };

    if (!isTypeScript) {
      parserOptions.ecmaFeatures = {
        ...parserOptions.ecmaFeatures,
        class: true,
      };
    }

    if (isTypeScript) {
      parserOptions.ecmaFeatures = {
        ...parserOptions.ecmaFeatures,
        jsx: filePath.endsWith('.tsx') || filePath.endsWith('.jsx'),
      };
    }

    console.log(
      `🔧 Парсинг с опциями: sourceType=${parserOptions.sourceType}, ecmaVersion=${parserOptions.ecmaVersion}`
    );

    const fallbackOptions: ParserOptions = {
      ecmaVersion: 2022 as const,
      sourceType: 'module',
      loc: true,
      range: true,
    };

    let ast;
    try {
      ast = parser.parse(code, parserOptions);
    } catch (parseError: any) {
      console.error(`❌ Ошибка парсинга ${resolvedPath}:`, parseError.message);
      if (parseError.stack) {
        console.error('📚 Стек ошибки:', parseError.stack);
      }

      try {
        console.log('🔄 Повторная попытка с упрощенными настройками...');
        ast = parser.parse(code, fallbackOptions);
        console.log('✅ Fallback парсинг успешен');
      } catch (fallbackError: any) {
        console.error(`❌ Fallback парсинг также не удался: ${fallbackError.message}`);
        if (fallbackError.stack) {
          console.error('📚 Стек fallback ошибки:', fallbackError.stack);
        }
        return null;
      }
    }

    if (!ast) {
      console.warn(`⚠️ AST не построен для файла: ${resolvedPath}`);
      return null;
    }

    if (!ast.body || !Array.isArray(ast.body)) {
      console.warn(`⚠️ AST не содержит body для файла: ${resolvedPath}`);
      return {
        ast: { type: 'Program', body: [], sourceType: 'module', comments: [], tokens: [] },
        filePath: resolvedPath,
        moduleName,
        isVue,
        isTypeScript,
        content: code,
        imports: [],
        exports: [],
      };
    }

    console.log(`✅ AST успешно построен, узлов верхнего уровня: ${ast.body.length}`);

    const nodeTypes = ast.body.slice(0, 5).map((n: any) => n?.type || 'unknown');
    console.log(`📋 Типы первых узлов: ${nodeTypes.join(', ')}`);

    const hasClasses = ast.body.some((n: any) => n?.type === 'ClassDeclaration');
    const hasFunctions = ast.body.some((n: any) => n?.type === 'FunctionDeclaration');
    const hasVariables = ast.body.some((n: any) => n?.type === 'VariableDeclaration');

    console.log(
      `📊 Содержимое AST: Classes=${hasClasses}, Functions=${hasFunctions}, Variables=${hasVariables}`
    );

    // ✅ СБОР ИМПОРТОВ И ЭКСПОРТОВ
    imports = collectImportsFromAST(ast);
    exports = collectExportsFromAST(ast);

    if (imports.length > 0) {
      console.log(`   📥 Найдено импортов: ${imports.length}`);
    }
    if (exports.length > 0) {
      console.log(`   📤 Найдено экспортов: ${exports.length}`);

      // ✅ ЛОГИРУЕМ РЕЭКСПОРТЫ
      const reExports = exports.filter(e => e.isReExport);
      if (reExports.length > 0) {
        console.log(`      🔄 Реэкспортов: ${reExports.length}`);
        for (const re of reExports.slice(0, 5)) {
          console.log(`         • ${re.name} from '${re.source}'`);
        }
        if (reExports.length > 5) {
          console.log(`         ... и ещё ${reExports.length - 5} реэкспортов`);
        }
      }
    }

    if (isVue && ast) {
      ast._originalCode = code;
      ast._isVue = true;
      ast._vueType = isTypeScript ? 'tsSetup' : 'setup';
    }

    // ✅ ВОЗВРАЩАЕМ РАСШИРЕННУЮ ИНФОРМАЦИЮ
    return {
      ast,
      filePath: resolvedPath,
      moduleName,
      isVue,
      isTypeScript,
      content: code,
      imports,
      exports,
    };
  } catch (e) {
    if (e instanceof Error && (e as any).code === 'ENOENT') {
      console.warn(`⚠️ Файл не найден: ${filePath}`);
      return null;
    }
    console.error(
      `❌ Ошибка парсинга файла ${filePath}:`,
      e instanceof Error ? e.message : String(e)
    );
    if (e instanceof Error && e.stack) {
      console.error('📚 Стек ошибки:', e.stack);
    }
    return null;
  }
}

{
  if (
    importTarget.startsWith('@') ||
    importTarget.startsWith('#') ||
    importTarget.startsWith('~')
  ) {
    return false;
  }

  return (
    !importTarget.startsWith('.') && !importTarget.startsWith('/') && !path.isAbsolute(importTarget)
  );
}

{
  // 1. Проверяем, не абсолютный ли уже путь
  if (path.isAbsolute(targetPath) && fs.existsSync(targetPath)) {
    return targetPath;
  }

  // 2. Используем getTsConfigForFile с кэшированием
  const tsConfig = getTsConfigForFile(baseDir);
  const tsConfigDir = getTsConfigDir() || baseDir;

  // 3. Проверяем алиасы из tsconfig
  const aliasedPath = resolveAliasPath(targetPath, tsConfigDir, tsConfig);
  if (aliasedPath && fs.existsSync(aliasedPath)) {
    console.log(`   🔗 Алиас: ${targetPath} → ${path.relative(process.cwd(), aliasedPath)}`);
    return aliasedPath;
  }

  // 4. Формируем полный путь
  const fullPath = path.resolve(baseDir, targetPath);

  // 5. Проверяем файл как есть (с текущим расширением)
  if (fs.existsSync(fullPath) && fs.statSync(fullPath).isFile()) {
    return fullPath;
  }

  // 6. Проверяем файл БЕЗ расширения (если в targetPath нет расширения)
  const hasExtension = path.extname(targetPath) !== '';
  if (!hasExtension && fs.existsSync(fullPath) && fs.statSync(fullPath).isFile()) {
    console.log(`   📄 Найден без расширения: ${targetPath}`);
    return fullPath;
  }

  // 7. Специальная проверка: .js → .ts (и наоборот)
  if (targetPath.endsWith('.js')) {
    const tsPath = fullPath.replace(/\.js$/, '.ts');
    if (fs.existsSync(tsPath) && fs.statSync(tsPath).isFile()) {
      console.log(`   🔄 .js → .ts: ${targetPath} → ${path.relative(process.cwd(), tsPath)}`);
      return tsPath;
    }
  }
  if (targetPath.endsWith('.ts')) {
    const jsPath = fullPath.replace(/\.ts$/, '.js');
    if (fs.existsSync(jsPath) && fs.statSync(jsPath).isFile()) {
      console.log(`   🔄 .ts → .js: ${targetPath} → ${path.relative(process.cwd(), jsPath)}`);
      return jsPath;
    }
  }

  // 8. Проверяем ВСЕ возможные расширения (ВКЛЮЧАЯ то, что уже проверяли)
  const extensions = ['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', ''];

  for (const ext of extensions) {
    // ✅ Убрана проверка: if (ext === targetExt) continue;
    // Теперь проверяем ВСЕ варианты, даже если они совпадают с исходным расширением
    const testPath = fullPath + ext;
    if (fs.existsSync(testPath) && fs.statSync(testPath).isFile()) {
      console.log(`   📄 Найден: ${targetPath} → ${path.relative(process.cwd(), testPath)}`);
      return testPath;
    }
  }

  // 9. Проверяем как директорию с index файлом
  if (fs.existsSync(fullPath) && fs.statSync(fullPath).isDirectory()) {
    for (const ext of extensions) {
      const indexPath = path.join(fullPath, `index${ext}`);
      if (fs.existsSync(indexPath) && fs.statSync(indexPath).isFile()) {
        console.log(`   📁 Директория → index${ext}: ${targetPath}`);
        return indexPath;
      }
    }
  }

  // 10. Проверяем относительно tsconfig директории
  if (tsConfigDir && tsConfigDir !== baseDir) {
    const fromRootPath = path.resolve(tsConfigDir, targetPath);

    // Проверяем файл как есть
    if (fs.existsSync(fromRootPath) && fs.statSync(fromRootPath).isFile()) {
      return fromRootPath;
    }

    // Проверяем без расширения
    if (!hasExtension && fs.existsSync(fromRootPath) && fs.statSync(fromRootPath).isFile()) {
      return fromRootPath;
    }

    // .js → .ts
    if (targetPath.endsWith('.js')) {
      const tsFromRoot = fromRootPath.replace(/\.js$/, '.ts');
      if (fs.existsSync(tsFromRoot) && fs.statSync(tsFromRoot).isFile()) {
        return tsFromRoot;
      }
    }

    // .ts → .js
    if (targetPath.endsWith('.ts')) {
      const jsFromRoot = fromRootPath.replace(/\.ts$/, '.js');
      if (fs.existsSync(jsFromRoot) && fs.statSync(jsFromRoot).isFile()) {
        return jsFromRoot;
      }
    }

    // Проверяем все расширения
    for (const ext of extensions) {
      const testPath = fromRootPath + ext;
