            )
          ) {
            affectedFunctions.add(currentFunctionName);
          }
        }
      },
      leave(node: any) {
        // Сбрасываем контекст при выходе из функции
        if (
          [
            'FunctionDeclaration',
            'ArrowFunctionExpression',
            'FunctionExpression',
            'MethodDefinition',
          ].includes(node.type)
        ) {
          currentFunctionName = 'Top-level (глобальный код)';
        }
      },
    });

