        if (lowlinkNode !== undefined && lowlinkNeighbor !== undefined) {
          lowlink[node] = Math.min(lowlinkNode, lowlinkNeighbor);
        } else if (lowlinkNeighbor !== undefined) {
          lowlink[node] = lowlinkNeighbor;
