    const lowlinkNode = lowlink[node];
    const indexNode = index[node];
    if (lowlinkNode !== undefined && indexNode !== undefined && lowlinkNode === indexNode) {
      const scc: string[] = [];
      let w: string | undefined;
      do {
        w = stack.pop();
        if (w) {
