      const isAsync = func.includes('async');

      if (nameMatch && nameMatch[1]) {
        const name = nameMatch[1];
        const params =
          paramsMatch && paramsMatch[1]
            ? paramsMatch[1]
                .split(',')
                .map((p: string) => p.trim())
                .filter((p: string) => p)
            : [];
        const body = bodyMatch && bodyMatch[1] ? bodyMatch[1].trim() : '';

