        const line = content.substring(0, func.indexOf(name)).split('\n').length;
        const startLine = content.substring(0, func.indexOf(name)).split('\n').length;
        const endLine = startLine + func.split('\n').length;

        functions.push({
          name,
          line,
          isExported,
          isAsync,
