        dot += `    "${funcId}" [fillcolor="${funcColor}", shape=ellipse, label="${funcLabel}", fontsize=10];\n`;
        dot += `    "${module.path}" -> "${funcId}" [style=dashed, color="#94a3b8", penwidth=0.5];\n`;

